import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"《文言传 * 乾文言》","description":"周易折中 - 《文言传 * 乾文言》","frontmatter":{"title":"《文言传 * 乾文言》","description":"周易折中 - 《文言传 * 乾文言》"},"headers":[],"relativePath":"zh/classics/zhezhong/073.md","filePath":"zh/classics/zhezhong/073.md"}'),h={name:"zh/classics/zhezhong/073.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="《文言传-乾文言》" tabindex="-1">《文言传 * 乾文言》 <a class="header-anchor" href="#《文言传-乾文言》" aria-label="Permalink to “《文言传 * 乾文言》”">​</a></h1><p>文言传</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>此篇申彖传象传之意，以尽乾坤二卦之蕴。而馀卦之说因可以例推云。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云：大抵易卦之辞本只是各著本卦本爻之象，明吉凶之占当如此耳。非是就圣贤地位说道理也，故干六爻自天子以至于庶人，自圣人以至于愚不肖筮或得之，义皆有取。但纯阳之徳刚健之至，若以义类推之，则为圣人之象。而其六位之下又冇似圣人之进退，故文言因潜见跃飞自然之文，而以圣人之迹各明其义。</li></ul><p>“元”者，善之长也；“亨”者，嘉之会也；“利”者，义之和也；“贞”者，事之干也。</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>元者生物之始，天地之徳莫先于此。故于时为春，于人则为仁而众善之长也。亨者生物之通，物至于此莫不嘉羙，故于时为夏，于人则为礼而众羙之㑹也。利者生物之遂，物各得宜不相妨害，故于时为秋，于人则为义而得其分之和。贞者生物之成，实理具备随在各足，故于时为冬，于人则为智而为众事之干。干，木之身而枝叶所依，以立者也。</p><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>它卦彖象而已，独乾坤更设文言以发明其义。推干之道施于人事，元亨利贞干之四徳，在人则元者众善之首也。亨者嘉美之㑹也，利者和合于义也，贞者干事之用也。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问：元者善之长曰元亨利贞皆善也，而元乃为四者之长是善端初发见处也。</p></li><li><p>问亨者嘉之㑹曰：且以草木言之，发生到夏时好处都来凑㑹。嘉只是好处，㑹是期㑹也。</p></li><li><p>又云利者义之和：义疑于不和矣，然处之而各得其所则和。义之和处便是利，义截然而不可犯，似不和分别后万物各止其所，却是和不和生于不义。义则无不和，和则无不利矣。</p></li><li><p>又云贞者事之干：知是那黙运事变底一件物。</p></li></ul><p>君子体仁足以长人，嘉会足以合礼，利物足以和义，贞固足以干事。</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以仁为体，则无一物不在所爱之中，故足以长人。嘉其所㑹，则无不合礼。使物各得其所，利则义无不和。贞固者，知正之所在而固守之，所谓知而弗去者也，故足以为事之干。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>体法于干之仁，乃为君长之道，足以长人也。体仁体元也，比而效之谓之体，得㑹通之嘉乃合于礼也。不合礼则非理，岂得为嘉，非理安有亨乎？和于义乃能利物，岂有不得其宜而能利物者乎？贞固所以能干事也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏鼎祚曰：天运四时以生成万物，君法五常以教化于人。元为善长，故能体仁，仁主春生，东方木也。通为嘉㑹，足以合礼，礼主夏养，南方火也。利为物宜，足以和义，义主秋成，西方金也。贞为事干，以配于智，智主冬藏，北方水也。不言信者，信主土，土居中宫，分王四季。水火金木非土不载。</p></li><li><p>朱子语类云：体仁不是将仁来为我之体，我之体便都是仁也。又曰本义云以仁为体者，犹言自家一个身体元来都是仁。 又云：嘉羙也，㑹是集齐底意思，许多嘉羙一时鬬凑到此，故谓之嘉㑹。嘉其所㑹便动容周旋无不中礼。 又云：看来义之为义，只是一个冝，其初则甚严。如男正位乎外，女正位乎内，直是有内外之办。君尊于上，臣恭于下，尊卑大小截然不可犯，似若不和之甚。然能使之各得其宜，则其和也孰大于是。 又云：干如木之干，事如木之枝叶，贞固者正而固守之。贞固在事是与立个骨子，所以为事之干。欲为事而非此之贞固，便植立不起，自然倒了。 问 贞固二字与体仁嘉㑹利物似不同， 曰 属北方者便著用两字方能尽之。</p></li><li><p>又云：嘉羙也，㑹是集齐底意思，许多嘉羙一时鬬凑到此，故谓之嘉㑹。嘉其所㑹便动容周旋无不中礼。</p></li><li><p>又云：看来义之为义，只是一个冝，其初则甚严。如男正位乎外，女正位乎内，直是有内外之办。君尊于上，臣恭于下，尊卑大小截然不可犯，似若不和之甚。然能使之各得其宜，则其和也孰大于是。</p></li><li><p>又云：干如木之干，事如木之枝叶，贞固者正而固守之。贞固在事是与立个骨子，所以为事之干。欲为事而非此之贞固，便植立不起，自然倒了。</p></li><li><p>问 贞固二字与体仁嘉㑹利物似不同， 曰 属北方者便著用两字方能尽之。</p></li><li><p>胡氏炳文曰：体仁有以存诸中，嘉㑹则美见乎外。利物有以方乎外，而贞固有以守于中。礼者仁之著，智者义之藏。体仁长人，贞固干事，由理以及用。嘉㑹合礼，利物和义，则由用以及理也。</p></li><li><p>董氏真卿曰：朱子谓属北方者便著用两字，方能尽之。㓜时闻先君子之言曰：北方天气之终始，有分别之义。故北字篆文，两人相背。至于四端五臓四兽，属北方者皆两。东西南三方者各一，四时为冬亦与春为交接。四徳为贞，亦贞下起元。十二辰为亥子，六十四卦为坤复。</p></li><li><p>林氏希元曰：君子克己复礼，使仁充乎中而见乎外。中之所存无一念之非仁，外之所行无一事之非仁，则君子之身浑是一个仁。非体其体而体夫仁也，体仁仁之至也。故无一物不在所爱之中，而足以长人。安土敦仁，故能爱正是如此。</p></li><li><p>又曰利者义之和：之利乃在人天然之利，利物足以和义之利。乃人所以求乎天然之利也，义之和之和乃在人天然之和。足以和义之和，乃人所以求乎天然之和也。</p></li></ul><p>君子行此四德者，故曰：“乾、元、亨、利、贞。”</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>非君子之至健无以行此，故曰乾元亨利贞。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>行此四徳乃合于干也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>朱子语类问：乾元亨利贞犹言性仁义礼智曰，此语甚稳当。</p></li><li><p>蔡氏清曰：元亨利贞四字在文王，只为占辞。至孔子彖传，乃有四徳之说。然其所谓四徳者又有不同，天之四徳自其生成万物者言也。圣人之四徳自其统治一世者言也，至此所谓四徳又只就君子一身所行而言也。一身所行者其体也，统治一世者其用也，四徳无乎不在也。又见干字所该者广也。</p></li></ul><p>初九曰：“潜龙勿用。”何谓也？子曰：“龙德而隐者也，不易乎世，不成乎名，遯世无闷，不见是而无闷，乐则行之，忧则违之，确乎其不可拔，潜龙也。”</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>龙徳圣人之徳也在下故隠，易谓变其所守。大抵乾卦六爻文言皆以圣人明之，有隠显而无浅深也。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>自此以下言干之用用九之道也。初九阳之微，龙徳之潜隠乃圣贤之在侧陋也。守其道不随世而变，晦其行不求知于时。自信自乐见可而动，知难而避。其守坚不可夺，潜龙之徳也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：心以为乐己则行，心以为忧己则违之。身虽逐物推移，心志守道确乎坚实，其不可㧞。</p></li><li><p>游氏酢曰：龙徳而隠故不易乎世，不易乎世者用舍在我，故遁世无闷。不成乎名者非誉不在物，故不见是而无闷。</p></li><li><p>吴氏澄曰：乐则行之释上文无闷二句，忧则违之释上文不易不成二句。乐者谓无闷也行之谓为之也，忧者谓非其所乐也违之谓不为也。不求见于世不求知于人者，此其所乐也则为之。易乎世成乎名者，此非其所乐也则不为。</p></li><li><p>蒋氏悌生曰：行道而济时者，圣人之夲心。故曰乐则行之，不用而隠遁者，非圣人之所愿欲也。故曰忧则违之，虽然其进其退莫不求至理之所在。未尝枉道以徇人也，故曰确乎其不可㧞。</p></li><li><p>蔡氏清曰：遁世无闷二句尤重于不易乎世二句，乐则行之三句更重于遁世无闷二句。此三句明其无意必也，论龙徳之隠必至是而后尽。</p></li></ul><p>九二曰：“见龙在田，利见大人。”何谓也？子曰：“龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。《易》曰‘见龙在田，利见大人’。君德也。”</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>正中不潜而未跃之时也，常言亦信常行亦谨盛徳之至也。闲邪存其诚无斁亦保之意，言君徳也者释大人之为九二也。</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>以龙徳而处正中者也，在卦之正中为得正中之义。庸信庸谨造次必于是也，既处无过之地，则唯在闲邪邪既闲则诚存矣。善世而不伐不有其善也，徳博而化正已而物正也，皆大人之事。虽非君位君之徳也。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：庸常也，常言之信实，常行之谨慎。防闲邪恶，自存诚实，为善于世而不自伐其功，徳能广博而变化于世俗。</p></li><li><p>朱子语类云：庸言庸行盛徳之至，到这里犹自闲邪存诚，便是无斁亦保。虽无厌斁亦当保也，保者持守之意。</p></li><li><p>陆氏九渊曰：言行之信谨二之所以成己者也，善世而不伐二之所以成物者也。彼其所谓信谨者，乃其所以不伐者也。闲邪存其诚存诸己者也，徳博而化徳之及乎物者也。彼其所以闲而存者，乃其所以博而化者也。</p></li><li><p>李氏舜臣曰：干画一实则诚，坤画一虗则生敬，故乾九二言诚，坤六二言敬。诚敬二字始于包牺心画，而实天地自然之理也。</p></li><li><p>项氏安世曰：称中正者二事也，二五为中，阴阳当位为正。称正中者一事也，但取其正得中位，非以当位言也。</p></li></ul><p>九三曰“君子终日乾乾，夕惕若厉，无咎”何谓也？子曰：君子进徳脩业，忠信所以进徳也，脩辞立其诚所以居业也。知至至之，可与几也；知终终之，可与存义也。是故居上位而不骄，在下位而不忧。故乾乾因其时而惕，虽危无咎矣</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>忠信主于心者无一念之不诚也，脩辞见于事者无一言之不实也。虽有忠信之心，然非脩辞立诚，则无以居之。知至至之进徳之事，知终终之居业之事，所以终日乾乾而夕犹惕若者，以此故也。可上可下不骄不忧，所谓无咎也。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>三居下之上而君徳已著，将何为哉？唯进徳脩业而已。内积忠信所以进徳也，择言笃志所以居业也。知至至之致知也，求知所至而后至之。知之在先，故可与㡬，所谓始条理者知之事也。知终终之，力行也。既知所终，则力进而终之。守之在后，故可与存义，所谓终条理者圣之事也。此学之始终也，君子之学如是，故知处上下之道而无骄忧。不懈而知惧，虽在危地而无咎也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：九三所以终日乾乾者，欲进益道徳脩营功业，故终日乾乾匪懈也。进徳则知至将进也，脩业则知终存义也。</p></li><li><p>程子曰：脩辞立其诚不可不子细，理㑹言能脩省言辞，便是要立诚。若只是脩饰言辞为心，只是为伪也。</p></li><li><p>吕氏大临曰：忠信进徳，如有诸己又知所以充实之也。脩辞立其诚，正名是事，行其实以称之也。所立卓尔而欲从之，知至至之也。于徳有先见之明也，人不堪其忧而不改其乐，知终终之也。于分有当安之义也。</p></li><li><p>朱子语类云：徳是就心上说，业是就事上说。忠信是自家心中诚实，脩辞立其诚是说处有真实底道理。 又云：忠信只是实，若无实如何㑹进。如播种相似，须是实有种子下在泥里，方㑹日见发生。若把个空壳下在里面，如何㑹发生。道理须是实见得，若徒将耳听过，将口说过，济甚事。忠信所以为实者，且如孝须实是孝，方始那孝之徳日进一日。如弟须实是弟，方始那弟之徳日进一日。若不实，却自无根了，如何㑹进。立其诚，诚依旧便是上面忠信，脩辞是言语照管得到那里面，亦须照管得到。进徳是自觉得意思日强似一日，日振作似一日，不是外面事，只是自见得意思不同。 问：立诚不就制行上说而特指脩辞何也。 曰 人不诚处多在言语上，又曰人多将言语作没紧要，容易说出来。若一一要实，这工夫自是大。忠信进徳便是见得脩辞立诚底许多道理，脩辞立诚便要立得这忠信。若口不择言，逢事便说，只这忠信亦被汨没动荡，立不住了。 又云：伊川解脩辞立其诚作择言笃志，说得来寛不如明道说云脩其言辞，正为立已之诚意。</p></li><li><p>又云：忠信只是实，若无实如何㑹进。如播种相似，须是实有种子下在泥里，方㑹日见发生。若把个空壳下在里面，如何㑹发生。道理须是实见得，若徒将耳听过，将口说过，济甚事。忠信所以为实者，且如孝须实是孝，方始那孝之徳日进一日。如弟须实是弟，方始那弟之徳日进一日。若不实，却自无根了，如何㑹进。立其诚，诚依旧便是上面忠信，脩辞是言语照管得到那里面，亦须照管得到。进徳是自觉得意思日强似一日，日振作似一日，不是外面事，只是自见得意思不同。</p></li><li><p>问：立诚不就制行上说而特指脩辞何也。 曰 人不诚处多在言语上，又曰人多将言语作没紧要，容易说出来。若一一要实，这工夫自是大。忠信进徳便是见得脩辞立诚底许多道理，脩辞立诚便要立得这忠信。若口不择言，逢事便说，只这忠信亦被汨没动荡，立不住了。</p></li><li><p>又云：伊川解脩辞立其诚作择言笃志，说得来寛不如明道说云脩其言辞，正为立已之诚意。</p></li></ul><p>九四曰“或跃在渊，无咎”何谓也？子曰：上下无常，非为邪也。进退无恒，非离群也。君子进徳脩业，欲及时也。故无咎</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>内卦以徳学言，外卦以时位言。进徳脩业九三备矣，此则欲其及时而进也。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>或跃或处，上下无常。或进或退，去就从宜。非为邪枉，非离群类。进徳脩业，欲及时耳。时行时止，不可恒也。故云或渊，渊者龙之所安也。在渊谓跃就所安，渊在深而言跃，但取进就所安之义。或疑辞随时而未可必也，君子之顺时，犹影之随形，可离非道也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>项氏安世曰：进退上下不敢自必，相时而动，所谓自试也。大抵上下之交皆危疑之地，故三厉而四犹疑之。</p></li><li><p>俞氏琰曰：试释跃字，与中庸日省月试之试同。君子谨失时之戒，而自试其所学，盖欲自知其浅深也。</p></li><li><p>谷氏家杰曰：人见者浅，自见者真，必自家试之而后可决也。</p></li></ul><p>九五曰“飞龙在天，利见大人”何谓也？子曰：同声相应，同气相求。水流湿，火就燥，云从龙，风从虎。圣人作而万物睹，本乎天者亲上，本乎地者亲下，则各从其类也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>作起也，物犹人也。睹释利见之意也，本乎天者谓动物，本乎地者谓植物。物各从其类，圣人人类之首也。故兴起于上，则人皆见之。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>人之与圣人类也，五以龙徳升尊位。人之类莫不归仰，况同徳乎？上应于下，下从于上。同声相应，同气相求也。流湿就燥，从龙从虎，皆以气类故。圣人作而万物皆睹，上既见下，下亦见上。物人也，古语云人物物论，谓人也。易中利见大人，其言则同。义则有异，如讼之利见大人。谓宜见大徳中正之人，则其辨明言在见前，干之二五则圣人既出。上下相见，共成其事，所利者见大人也，言在见后。本乎天者如日月星辰，本乎地者如虫兽草木。阴阳各从其类，人物莫不然也。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：因大人与众物感应，故广陈众物相感应，以明圣人之作而万物瞻睹，以结之也。</p></li><li><p>朱子语类云：天下所患无君，不患无臣。有如是君，必有如是臣。虽使而今无少闲也，必有出来。</p></li></ul><p>上九曰“亢龙有悔”何谓也？子曰：贵而无位，髙而无民。贤人在下位而无辅，是以动而有悔也</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>贤人在下位谓九五以下无辅以上九过髙，志满不来辅助之也。</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>九居上而不当尊位，是以无民无辅。动则有悔也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>谷氏家杰曰：以有位谓之贵，以有民谓之髙。以有辅谓之贤人在下位，其贵而又无位，髙而又无民。贤人在下位而又无辅者，何俱以亢失之也，故动而有悔。</li></ul><p>“潜龙勿用”，下也；</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>此以下言干之时，勿用以在下未可用也。</p><p>“见龙在田”，时舍也；</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>言未为时用也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>随时而止也。</p><p>“终日乾乾”，行事也；</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>进徳脩业也。</p><p>“或跃在渊”，自试也；</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>未遽有为，姑试其可。</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>随时自用也。</p><p>“飞龙在天”，上治也；</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>居上以治下。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>得位而行上之治也。</p><p>“亢龙有悔”，穷之灾也；</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>穷极而灾至也。</p><p>乾元“用九”，天下治也。</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>言乾元用九见与它卦不同，君道刚而能柔，天下无不治矣。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>用九之道天与圣人同得其用，则天下治也。</p><p>“潜龙勿用”，阳气潜藏；</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>此以下言干之义，方阳微潜藏之时，君子亦当晦隐，未可用也。</p><p>“见龙在田”，天下文明；</p><h3 id="本义-14" tabindex="-1">本义 <a class="header-anchor" href="#本义-14" aria-label="Permalink to “本义”">​</a></h3><p>虽不在上位，然天下已被其化。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>龙徳见于地上，则天下见其文明而化之。</p><p>“终日乾乾”，与时偕行；</p><h3 id="本义-15" tabindex="-1">本义 <a class="header-anchor" href="#本义-15" aria-label="Permalink to “本义”">​</a></h3><p>时当然也。</p><p>“或跃在渊”，乾道乃革；</p><h3 id="本义-16" tabindex="-1">本义 <a class="header-anchor" href="#本义-16" aria-label="Permalink to “本义”">​</a></h3><p>离下而上，变革之时。</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>离下位而升上位，上下革矣。</p><p>“飞龙在天”，乃位乎天德；</p><h3 id="本义-17" tabindex="-1">本义 <a class="header-anchor" href="#本义-17" aria-label="Permalink to “本义”">​</a></h3><p>天徳即天位也，盖唯有是徳乃宜居是位，故以名之。</p><h3 id="程传-19" tabindex="-1">程传 <a class="header-anchor" href="#程传-19" aria-label="Permalink to “程传”">​</a></h3><p>正位乎上位，当天徳矣。</p><p>“亢龙有悔”，与时偕极；</p><h3 id="程传-20" tabindex="-1">程传 <a class="header-anchor" href="#程传-20" aria-label="Permalink to “程传”">​</a></h3><p>时既极则处时者亦极矣。</p><p>乾元“用九”，乃见天则。</p><h3 id="本义-18" tabindex="-1">本义 <a class="header-anchor" href="#本义-18" aria-label="Permalink to “本义”">​</a></h3><p>刚而能柔，天之法也。</p><h3 id="程传-21" tabindex="-1">程传 <a class="header-anchor" href="#程传-21" aria-label="Permalink to “程传”">​</a></h3><p>用九之道天之则也，天之法则谓天道也。</p><p>乾“元”者，始而亨者也；</p><h3 id="本义-19" tabindex="-1">本义 <a class="header-anchor" href="#本义-19" aria-label="Permalink to “本义”">​</a></h3><p>始则必亨，理势然也。</p><h3 id="程传-22" tabindex="-1">程传 <a class="header-anchor" href="#程传-22" aria-label="Permalink to “程传”">​</a></h3><p>又反复详说以尽其义，既始则必亨。不亨则息矣。</p><p>“利贞”者，性情也。</p><h3 id="本义-20" tabindex="-1">本义 <a class="header-anchor" href="#本义-20" aria-label="Permalink to “本义”">​</a></h3><p>收敛归藏，乃见性情之实。</p><h3 id="程传-23" tabindex="-1">程传 <a class="header-anchor" href="#程传-23" aria-label="Permalink to “程传”">​</a></h3><p>干之性情也，既始而亨。非利贞其能不息乎？</p><p>乾始能以美利利天下，不言所利，大矣哉，</p><h3 id="本义-21" tabindex="-1">本义 <a class="header-anchor" href="#本义-21" aria-label="Permalink to “本义”">​</a></h3><p>始者元而亨也，利天下者利也不言所利者贞也。</p><h3 id="程传-24" tabindex="-1">程传 <a class="header-anchor" href="#程传-24" aria-label="Permalink to “程传”">​</a></h3><p>乾始之道能使庶类生成，天下䝉其羙利而不言所利者。盖无所不利，非可指名也，故赞其利之大曰大矣哉。</p><p>大哉乾乎，刚健中正，纯粹精也。</p><h3 id="本义-22" tabindex="-1">本义 <a class="header-anchor" href="#本义-22" aria-label="Permalink to “本义”">​</a></h3><p>刚以体言，健兼用言。中者其行无过不及，正者其立不偏，四者干之徳也。纯者不杂于阴柔，粹者不杂于邪恶。盖刚健中正之至极而精者，又纯粹之至极也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><ul><li>乔氏中和曰：刚者元也，健者亨也。中者利也，正者贞也。元亨利贞实以体之刚健中正也，一爻之情，六爻之情也。</li></ul><p>六爻发挥，旁通情也，</p><h3 id="本义-23" tabindex="-1">本义 <a class="header-anchor" href="#本义-23" aria-label="Permalink to “本义”">​</a></h3><p>旁通犹言曲尽。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰：曲尽其义者，在六爻而备全其徳者，在九五。一爻时乘六龙以下，则为九五而言也。</li></ul><p>时乘六龙，以御天也。云行雨施，天下平也。</p><h3 id="本义-24" tabindex="-1">本义 <a class="header-anchor" href="#本义-24" aria-label="Permalink to “本义”">​</a></h3><p>言圣人时乘六龙以御天，则如天之云行雨施而天下平也。</p><h3 id="程传-25" tabindex="-1">程传 <a class="header-anchor" href="#程传-25" aria-label="Permalink to “程传”">​</a></h3><p>大哉赞乾道之大也，以刚健中正纯粹六者形容乾道精。谓六者之精极，以六爻发挥旁通尽其情义。乘六爻之时以当天运，则天之功用着矣。故见云行雨施，阴阳溥畅，天下和平之道也。</p><p>君子以成德为行，日可见之行也。“潜”之为言也，隐而未见，行而未成，是以君子弗用也。</p><h3 id="本义-25" tabindex="-1">本义 <a class="header-anchor" href="#本义-25" aria-label="Permalink to “本义”">​</a></h3><p>成徳已成之徳也，初九固成徳。但其行未可见尔。</p><h3 id="程传-26" tabindex="-1">程传 <a class="header-anchor" href="#程传-26" aria-label="Permalink to “程传”">​</a></h3><p>徳之成，其事可见者行也。徳成而后可施于用，初方潜隐未见其行。未成未著也是以君子弗用也。</p><p>君子学以聚之，问以辩之，宽以居之，仁以行之。《易》曰：“见龙在田，利见大人。”君德也。</p><h3 id="本义-26" tabindex="-1">本义 <a class="header-anchor" href="#本义-26" aria-label="Permalink to “本义”">​</a></h3><p>盖由四者以成大人之徳，再言君徳以深明九二之为大人也。</p><h3 id="程传-27" tabindex="-1">程传 <a class="header-anchor" href="#程传-27" aria-label="Permalink to “程传”">​</a></h3><p>圣人在下虽已显而未得位，则进徳修业而已。学聚问辨进徳也，寛居仁行修业也。君徳已著，利见大人而进以行之耳。进居其位者舜禹也，进行其道者伊傅也。</p><p>九三重刚而不中，上不在天，下不在田，故乾乾因其时而惕，虽危“无咎”矣。</p><h3 id="本义-27" tabindex="-1">本义 <a class="header-anchor" href="#本义-27" aria-label="Permalink to “本义”">​</a></h3><p>重刚谓阳爻阳位。</p><h3 id="程传-28" tabindex="-1">程传 <a class="header-anchor" href="#程传-28" aria-label="Permalink to “程传”">​</a></h3><p>三重刚刚之盛也，过中而居下之上。上未至于天而下已离于田，危惧之地也。因时顺处，乾乾兢惕以防危，故虽危而不至于咎。君子顺时兢惕所以能泰也。</p><p>九四重刚而不中，上不在天，下不在田，中不在人，故“或”之，或之者，疑之也。故“无咎”。</p><h3 id="本义-28" tabindex="-1">本义 <a class="header-anchor" href="#本义-28" aria-label="Permalink to “本义”">​</a></h3><p>九四非重刚，重字疑衍。在人谓三或者随时而未定也。</p><h3 id="程传-29" tabindex="-1">程传 <a class="header-anchor" href="#程传-29" aria-label="Permalink to “程传”">​</a></h3><p>四不在天不在田而出人之上矣，危地也。疑者未决之辞，处非可必也。或进或退，唯所安耳。所以无咎也。</p><p>夫“大人”者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天而天弗违，后天而奉天时，天且弗违，而况于人乎！况于鬼神乎！</p><h3 id="本义-29" tabindex="-1">本义 <a class="header-anchor" href="#本义-29" aria-label="Permalink to “本义”">​</a></h3><p>大人即释爻辞所利见之大人也。有是徳而当其位，乃可当之人与天地鬼神本无二理。特蔽于有我之私，是以牿于形体而不能相通。大人无私以道为体，曽何彼此先后之可言哉。先天不违谓意之所为黙与道契，后天奉天谓知理如是奉而行之。</p><h3 id="程传-30" tabindex="-1">程传 <a class="header-anchor" href="#程传-30" aria-label="Permalink to “程传”">​</a></h3><p>大人与天地日月四时鬼神合者，合乎道也。天地者道也，鬼神者造化之迹也。圣人先于天而天同之，后于天而能顺天者，合于道而已。合于道则人与鬼神，岂能违也。</p><p>“亢”之为言也，知进而不知退，知存而不知亡，知得而不知丧，</p><h3 id="本义-30" tabindex="-1">本义 <a class="header-anchor" href="#本义-30" aria-label="Permalink to “本义”">​</a></h3><p>所以动而有悔也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>孔氏颖逹曰：言上九所以亢极有悔者，正由有此三事。若能三事备知，虽居上位不至于亢也。</li></ul><p>其唯圣人乎！知进退存亡而不失其正者，其唯圣人乎！</p><h3 id="本义-31" tabindex="-1">本义 <a class="header-anchor" href="#本义-31" aria-label="Permalink to “本义”">​</a></h3><p>知其理势如是而处之以道，则不至于有悔矣。固非计私以避害者也。再言“其唯圣人乎”，始若设问而卒自应之也。○此苐六莭，复申苐二、苐三、苐四莭之意。</p><h3 id="程传-31" tabindex="-1">程传 <a class="header-anchor" href="#程传-31" aria-label="Permalink to “程传”">​</a></h3><p>极之甚为亢，至于亢者不知进退存亡得丧之理也。圣人则知而处之，皆不失其正，故不至于亢也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>李氏鼎祚曰：再称圣人者，叹羙用九能知进退存亡而不失其正。</p></li><li><p>朱氏震曰：亢者处极而不知反也。万物之理，进必有退，存必有亡，得必有丧。亢知一而不知二，故道穷而致灾。人固有知进退存亡者矣，其道诡于圣人，则未必得其正。不得其正则与天地不相似。知进退存亡而不失其正者，其唯圣人乎！故两言之。</p></li><li><p>胡氏炳文曰：阳极则剥，干上则亢，中不可过也。知其时将过乎中而处之不失其正，其唯圣人乎！贞者，正也。乾元之用所归宿也。干之四徳始于元，至此又论圣人之体干而归于正，其意深矣。</p></li><li><p>陈氏琛曰：进极必退，存极必亡，乃理势之自然也。知其如是，则随时变通而处。以是道之当然有收敛而无施张，有舍弃而无系吝，如此则不至于有悔矣。然此唯圣人能之，盖圣人乐天知命，逹理而能权也。常人则明不足以见㡬，心不免于物累，故不能也。</p></li></ul><p>总论</p><p>朱子答万正淳曰：大抵易卦之辞，本只是各著本卦本爻之象，明吉凶之占当如此耳。非是就圣贤地位说道理也。故干六爻，自天子以至于庶人，自圣人以至于愚不肖，筮或得之义皆有取。但纯阳之徳，刚健之至，若以义类推之，则为圣人之象。而其六位之髙下，又冇似圣人之进退。故文言因潜见跃飞自然之文，而以圣人之迹各明其义。</p>',196)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
